// Level-up: the rules data (generated by srd/gen_levelup.py) and what the level-up screen works with.
import type { Ability } from "../rules";

export type Text = { name: string; text: string };
export type Opt = Text & { prereq?: string; minLevel?: number; level?: number; tags?: string[]; school?: string };

export type DataChoice = {
  key: string; kind: "pick" | "expertise" | "spells" | "weapons"; title: string; choose: number;
  options?: Opt[] | string;       // inline options, or the name of a shared list ("invocations", "metamagic", "fighting-style")
  level?: number;                 // spells: exactly this spell level (Mystic Arcanum)
  limit?: string[];               // expertise: only these skills (Scholar)
};
export type LevelRow = {
  features: Text[]; choices: DataChoice[]; asi: boolean; boon: boolean; subclassPick: boolean; pb: number | null;
  cantrips: number | null; known: number | null; prepared: number | null; slots: number[] | null; cs: Record<string, number>;
};
export type SubclassData = { name: string; flavor: string; text: string; levels: Record<string, Text[]>; choices: Record<string, DataChoice[]> };
export type ClassData = {
  hitDie: number; subclassLevel: number;
  mcPrereq: [Ability, number][][];  // every group must be met; inside a group, any one ability
  mcProf: string[]; mcSkills: { choose: number; from: string[] } | null;
  levels: Record<string, LevelRow>; subclasses: SubclassData[];
};
export type RulesData = {
  rules: "2014" | "2024";
  classes: Record<string, ClassData>;
  options: Record<string, Opt[]>;
  feats: { name: string; category: string | null; prereq: string | null; text: string }[];
  spells?: Record<string, string[]>;        // 2014: spell name → classes that have it
  weapons?: { name: string; mastery: string | null }[];
};

/** A spell from the app's spell library (srd_spells), trimmed for the lists. */
export type SpellLite = {
  name: string; level: number; school: string | null; classes: string[]; concentration: boolean; ritual: boolean;
  casting_time: string | null; range: string | null; duration: string | null; description: string;
};

export type ChoiceKind = "subclass" | "asi" | "pick" | "expertise" | "cantrips" | "spells" | "swap-out" | "swap-in" | "weapons" | "skills";
export type Choice = {
  key: string; kind: ChoiceKind; title: string; help: string; choose: number; options: Opt[];
  optional?: boolean;             // can be skipped (swapping a spell)
  forSubclass?: string;           // only if this subclass is picked now
  boon?: boolean;                 // asi: level 19 Epic Boon (a feat, boons first)
  gives?: Record<string, Text[]>; // subclass: what each option gives you right away
};
export type Plan = {
  className: string; isNew: boolean; fromLevel: number; toLevel: number; totalLevel: number; rules: "2014" | "2024";
  hitDie: number; average: number; conMod: number;
  subclass: string | null;        // the subclass already chosen (null = none yet)
  auto: (Text & { source: string })[];
  gains: string[];
  choices: Choice[];
  warnings: string[];
};

export type AsiAnswer = { mode: "plus2"; a: Ability } | { mode: "split"; a: Ability; b: Ability } | { mode: "feat"; feat: string; ability?: Ability };
export type Answers = { picks: Record<string, string[]>; asi?: Record<string, AsiAnswer>; hp: "average" | "roll" };
